package com.pablo.controlgastos;
import android.app.*;import android.content.*;import android.graphics.Color;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public class EmailSettingsActivity extends Activity{
 SharedPreferences p;int BG,TEXT,CARD,MUTED;EditText email,pass,host,cardMonths,expenseMonths;Switch enableCards,enableExpenses,cardAmount,cardText,cardCurrency,cardDate,cardLast4,expenseDate,expenseAmount,expenseCurrency,expenseExact,expenseSimilar;
 public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);p=getSharedPreferences(EmailSyncEngine.PREF,MODE_PRIVATE);boolean l=ThemePrefs.isLight(this);BG=l?0xfff6f8f9:0xff0b1218;TEXT=l?0xff1f262c:0xfff2f5f7;CARD=l?Color.WHITE:0xff162029;MUTED=l?0xff5f6970:0xff9ea9b2;build();}
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}TextView tv(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(TEXT);v.setPadding(dp(8),dp(8),dp(8),dp(8));return v;}Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}Switch sw(String s,boolean on){Switch x=new Switch(this);x.setText(s);x.setTextColor(TEXT);x.setChecked(on);x.setPadding(dp(8),dp(6),dp(8),dp(6));return x;}EditText ed(String hint,String val){EditText e=new EditText(this);e.setHint(hint);e.setText(val);e.setTextColor(TEXT);e.setHintTextColor(MUTED);return e;}EditText months(String hint,int val){EditText e=ed(hint,String.valueOf(val));e.setInputType(InputType.TYPE_CLASS_NUMBER);return e;}void title(LinearLayout r,String s){Space sp=new Space(this);r.addView(sp,new LinearLayout.LayoutParams(1,dp(26)));TextView t=tv(s,14);t.setTextColor(MUTED);r.addView(t);}void add(LinearLayout r,View v){r.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 void build(){LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setBackgroundColor(BG);ScrollView sc=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(18),dp(18),dp(18),dp(24));r.setBackgroundColor(BG);sc.addView(r);outer.addView(sc,new LinearLayout.LayoutParams(-1,0,1));r.addView(tv("Correo y lecturas",27));r.addView(tv("Podés configurar por separado cuántos meses hacia atrás revisar para tarjetas y para gastos. Por defecto se revisa 1 mes.",14));title(r,"CUENTA DE CORREO");email=ed("Correo",p.getString("email",""));pass=ed("Contraseña de aplicación",SecretStore.get(this));pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);host=ed("Servidor IMAP",p.getString("host","imap.gmail.com"));add(r,email);add(r,pass);add(r,host);Button test=btn("Probar conexión");add(r,test);test.setOnClickListener(v->testConnection());title(r,"TARJETAS DE CRÉDITO");enableCards=sw("Leer estados de tarjetas desde el correo",p.getBoolean("enable_cards",true));add(r,enableCards);cardMonths=months("Meses hacia atrás para estados",p.getInt("card_months_back",1));add(r,cardMonths);Button wlCard=btn("Administrar lista blanca de tarjetas");add(r,wlCard);wlCard.setOnClickListener(v->openWhitelist("card_whitelist","Lista blanca · Tarjetas"));r.addView(tv("Comparación para identificar el PAGO TOTAL. Solo se exigen los criterios activados:",13));cardAmount=sw("Mismo importe total",p.getBoolean("card_cmp_amount",true));cardText=sw("Texto PAGO TC / PAGO DE TARJETA",p.getBoolean("card_cmp_text",true));cardCurrency=sw("Misma moneda",p.getBoolean("card_cmp_currency",true));cardDate=sw("Fecha cercana al vencimiento",p.getBoolean("card_cmp_due_date",false));cardLast4=sw("Últimos 4 dígitos presentes",p.getBoolean("card_cmp_last4",false));for(Switch x:new Switch[]{cardAmount,cardText,cardCurrency,cardDate,cardLast4})add(r,x);Button readCards=btn("Leer estados de tarjeta");add(r,readCards);readCards.setOnClickListener(v->runCards());title(r,"GASTOS DESDE CORREO");enableExpenses=sw("Tomar gastos desde el correo",p.getBoolean("enable_expenses",false));add(r,enableExpenses);expenseMonths=months("Meses hacia atrás para gastos",p.getInt("expense_months_back",1));add(r,expenseMonths);Button wlExpense=btn("Administrar lista blanca de gastos");add(r,wlExpense);wlExpense.setOnClickListener(v->openWhitelist("expense_whitelist","Lista blanca · Gastos"));r.addView(tv("Comparación para evitar duplicados. Todos los criterios activados deben coincidir:",13));expenseDate=sw("Misma fecha",p.getBoolean("expense_cmp_date",true));expenseAmount=sw("Mismo importe",p.getBoolean("expense_cmp_amount",true));expenseCurrency=sw("Misma moneda",p.getBoolean("expense_cmp_currency",true));expenseExact=sw("Mismo nombre exacto",p.getBoolean("expense_cmp_exact_name",false));expenseSimilar=sw("Nombre parecido",p.getBoolean("expense_cmp_similar_name",true));for(Switch x:new Switch[]{expenseDate,expenseAmount,expenseCurrency,expenseExact,expenseSimilar})add(r,x);expenseExact.setOnCheckedChangeListener((x,on)->{if(on)expenseSimilar.setChecked(false);});expenseSimilar.setOnCheckedChangeListener((x,on)->{if(on)expenseExact.setChecked(false);});Button readExpenses=btn("Leer gastos del correo");add(r,readExpenses);readExpenses.setOnClickListener(v->runExpenses());Space end=new Space(this);r.addView(end,new LinearLayout.LayoutParams(1,dp(12)));Button save=btn("Guardar configuración");LinearLayout.LayoutParams slp=new LinearLayout.LayoutParams(-1,-2);slp.setMargins(dp(18),dp(6),dp(18),dp(10));outer.addView(save,slp);save.setOnClickListener(v->{if(save())Toast.makeText(this,"Configuración guardada",Toast.LENGTH_SHORT).show();});outer.setOnApplyWindowInsetsListener((v,in)->{int top=in.getSystemWindowInsetTop(),bottom=in.getSystemWindowInsetBottom();r.setPadding(dp(18),top+dp(14),dp(18),dp(24));LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)save.getLayoutParams();lp.bottomMargin=bottom+dp(10);save.setLayoutParams(lp);return in;});setContentView(outer);outer.requestApplyInsets();}
 int value(EditText e,String what){try{int n=Integer.parseInt(e.getText().toString().trim());if(n<1||n>24)throw new Exception();return n;}catch(Exception ex){Toast.makeText(this,what+" debe estar entre 1 y 24 meses",Toast.LENGTH_LONG).show();return-1;}}
 void openWhitelist(String k,String t){Intent i=new Intent(this,WhitelistEditorActivity.class);i.putExtra("key",k);i.putExtra("title",t);startActivity(i);}boolean save(){int cm=value(cardMonths,"El período de tarjetas");if(cm<0)return false;int em=value(expenseMonths,"El período de gastos");if(em<0)return false;if(enableCards.isChecked()&&p.getString("card_whitelist","sistarbanc|Estado de cuenta").trim().isEmpty()){Toast.makeText(this,"Agregá al menos una regla para tarjetas",Toast.LENGTH_LONG).show();return false;}if(enableExpenses.isChecked()&&p.getString("expense_whitelist","").trim().isEmpty()){Toast.makeText(this,"Agregá al menos una regla para gastos",Toast.LENGTH_LONG).show();return false;}p.edit().putString("email",email.getText().toString().trim()).putString("host",host.getText().toString().trim()).putInt("card_months_back",cm).putInt("expense_months_back",em).putBoolean("enable_cards",enableCards.isChecked()).putBoolean("enable_expenses",enableExpenses.isChecked()).putBoolean("card_cmp_amount",cardAmount.isChecked()).putBoolean("card_cmp_text",cardText.isChecked()).putBoolean("card_cmp_currency",cardCurrency.isChecked()).putBoolean("card_cmp_due_date",cardDate.isChecked()).putBoolean("card_cmp_last4",cardLast4.isChecked()).putBoolean("pay_amount",cardAmount.isChecked()).putBoolean("pay_text",cardText.isChecked()).putBoolean("expense_cmp_date",expenseDate.isChecked()).putBoolean("expense_cmp_amount",expenseAmount.isChecked()).putBoolean("expense_cmp_currency",expenseCurrency.isChecked()).putBoolean("expense_cmp_exact_name",expenseExact.isChecked()).putBoolean("expense_cmp_similar_name",expenseSimilar.isChecked()).remove("pass").apply();SecretStore.put(this,pass.getText().toString());return true;}
 void testConnection(){if(!save())return;ProgressDialog d=ProgressDialog.show(this,"Correo","Probando conexión IMAP…",true,false);new Thread(()->{try{EmailSyncEngine.testConnection(this);runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(this).setTitle("Conexión correcta").setMessage("ControlGastos pudo conectarse al correo configurado.").setPositiveButton("Aceptar",null).show();});}catch(Exception e){runOnUiThread(()->{d.dismiss();error(e,true);});}}).start();}
 void runCards(){if(!save())return;int n=p.getInt("card_months_back",1);ProgressDialog d=ProgressDialog.show(this,"Tarjetas","Buscando estados de los últimos "+n+(n==1?" mes…":" meses…"),true,false);new Thread(()->{try{EmailSyncEngine.Result x=EmailSyncEngine.readCards(this,true);runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(this).setTitle("Lectura terminada").setMessage(x.toString()).setPositiveButton("Aceptar",null).show();});}catch(Exception e){runOnUiThread(()->{d.dismiss();error(e,false);});}}).start();}
 void runExpenses(){if(!save())return;int n=p.getInt("expense_months_back",1);ProgressDialog d=ProgressDialog.show(this,"Gastos por correo","Buscando gastos de los últimos "+n+(n==1?" mes…":" meses…"),true,false);new Thread(()->{try{EmailSyncEngine.Result x=EmailSyncEngine.readExpenses(this,true);runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(this).setTitle("Lectura terminada").setMessage(x.toString()).setPositiveButton("Aceptar",null).show();});}catch(Exception e){runOnUiThread(()->{d.dismiss();error(e,false);});}}).start();}
 void error(Exception e,boolean connection){String m=e.getMessage()==null?e.toString():e.getMessage();if(connection)m+="\n\nSi usás Gmail, verificá el correo, la contraseña de aplicación y que la verificación en dos pasos esté habilitada.";new AlertDialog.Builder(this).setTitle(connection?"No se pudo conectar al correo":"No se pudo completar la lectura").setMessage(m).setPositiveButton("Aceptar",null).show();}
}
